1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"io"
7		"strings"
8		"testing"
9	)
10	
11	// runNormalize parses every emitted result line into ordered maps so tests
12	// can inspect JSON key order and type preservation in extra.
13	func runNormalize(t *testing.T, input string) []map[string]any {
14		t.Helper()
15		var out bytes.Buffer
16		failures, err := NormalizeReader(strings.NewReader(input), &out)
17		if err != nil {
18			t.Fatalf("NormalizeReader returned error: %v", err)
19		}
20		results := []map[string]any{}
21		dec := json.NewDecoder(bytes.NewReader(out.Bytes()))
22		for {
23			var m map[string]any
24			if err := dec.Decode(&m); err != nil {
25				if err == io.EOF {
26					break
27				}
28				t.Fatalf("decoding result: %v", err)
29			}
30			results = append(results, m)
31		}
32		if got := countFailures(results); got != failures {
33			t.Fatalf("NormalizeReader returned %d failures but output shows %d", failures, got)
34		}
35		return results
36	}
37	
38	func countFailures(results []map[string]any) int {
39		n := 0
40		for _, r := range results {
41			if r["ok"] == false {
42				n++
43			}
44		}
45		return n
46	}
47	
48	func eventOf(t *testing.T, r map[string]any) map[string]any {
49		t.Helper()
50		event, ok := r["event"].(map[string]any)
51		if !ok {
52			t.Fatalf("result has no event: %#v", r)
53		}
54		return event
55	}
56	
57	func TestNormalizeBasicAliases(t *testing.T) {
58		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":"login","user":" alice ","role":"admin","retries":2,"ok":true}`
59		results := runNormalize(t, input)
60		if len(results) != 1 || results[0]["ok"] != true {
61			t.Fatalf("expected one ok result, got %#v", results)
62		}
63		event := eventOf(t, results[0])
64		if event["timestamp"] != "2026-01-02T00:04:05Z" {
65			t.Fatalf("timestamp not converted to UTC RFC3339Nano: %v", event["timestamp"])
66		}
67		if event["source_ip"] != "2001:db8::1" {
68			t.Fatalf("source_ip mismatch: %v", event["source_ip"])
69		}
70		if event["action"] != "login" {
71			t.Fatalf("action mismatch: %v", event["action"])
72		}
73		extra := event["extra"].(map[string]any)
74		if extra["user"] != " alice " {
75			t.Fatalf("extra string must be preserved verbatim, got %v", extra["user"])
76		}
77		if extra["role"] != "admin" {
78			t.Fatalf("extra role mismatch: %v", extra["role"])
79		}
80		if extra["retries"] != float64(2) {
81			t.Fatalf("extra number must be preserved, got %v", extra["retries"])
82		}
83		if extra["ok"] != true {
84			t.Fatalf("extra boolean must be preserved, got %v", extra["ok"])
85		}
86	}
87	
88	func TestNormalizeCanonicalNames(t *testing.T) {
89		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"logout"}`
90		results := runNormalize(t, input)
91		event := eventOf(t, results[0])
92		if event["timestamp"] != "2026-01-02T00:00:00Z" || event["action"] != "logout" {
93			t.Fatalf("unexpected event: %#v", event)
94		}
95		if _, exists := event["source_ip"]; exists {
96			t.Fatalf("absent source_ip must not be serialized")
97		}
98		if _, exists := event["extra"]; exists {
99			t.Fatalf("empty extra must not be serialized")
100		}
101	}
102	
103	func TestNormalizeTrimsMappedStrings(t *testing.T) {
104		input := `{"timestamp":"  2026-01-02T00:00:00Z  ","source_ip":" 127.0.0.1 ","action":"  x  "}`
105		results := runNormalize(t, input)
106		if results[0]["ok"] != true {
107			t.Fatalf("expected ok, got %#v", results[0])
108		}
109		event := eventOf(t, results[0])
110		if event["timestamp"] != "2026-01-02T00:00:00Z" {
111			t.Fatalf("timestamp not trimmed: %v", event["timestamp"])
112		}
113		if event["source_ip"] != "127.0.0.1" {
114			t.Fatalf("source_ip not trimmed: %v", event["source_ip"])
115		}
116		if event["action"] != "x" {
117			t.Fatalf("action not trimmed: %v", event["action"])
118		}
119	}
120	
121	func TestNormalizeIPEquivalence(t *testing.T) {
122		pairs := [][]string{
123			{"127.0.0.1", "127.0.0.1"},
124			{"0:0:0:0:0:0:0:1", "::1"},
125			{"2001:DB8:0:0:0:0:0:1", "2001:db8::1"},
126			{"::ffff:192.0.2.1", "192.0.2.1"},
127			{"::", "::"},
128		}
129		for _, pair := range pairs {
130			for _, raw := range pair {
131				input := `{"timestamp":"2026-01-02T00:00:00Z","src_ip":"` + raw + `","action":"a"}`
132				results := runNormalize(t, input)
133				if results[0]["ok"] != true {
134					t.Fatalf("ip %q failed: %#v", raw, results[0])
135				}
136				got := eventOf(t, results[0])["source_ip"]
137				if got != pair[1] {
138					t.Fatalf("ip %q normalized to %v, want %q", raw, got, pair[1])
139				}
140			}
141		}
142	}
143	
144	func TestNormalizeInvalidIPs(t *testing.T) {
145		for _, ip := range []string{"127.0.0.1:80", "[::1]:443", "999.1.1.1", "192.168.001.001", "fe80::1%eth0", "not-an-ip", "1.2.3"} {
146			input := `{"timestamp":"2026-01-02T00:00:00Z","source_ip":"` + ip + `","action":"a"}`
147			results := runNormalize(t, input)
148			if results[0]["ok"] != false {
149				t.Fatalf("ip %q should fail", ip)
150			}
151			msg, _ := results[0]["error"].(string)
152			if !strings.Contains(msg, FieldSourceIP) {
153				t.Fatalf("error for ip %q must name field %q, got %q", ip, FieldSourceIP, msg)
154			}
155		}
156	}
157	
158	func TestNormalizeWhitespaceOnlyIPFails(t *testing.T) {
159		input := `{"timestamp":"2026-01-02T00:00:00Z","source_ip":"   ","action":"a"}`
160		results := runNormalize(t, input)
161		if results[0]["ok"] != false {
162			t.Fatalf("whitespace-only source_ip must not count as omitted")
163		}
164	}
165	
166	func TestNormalizeTimestampFormats(t *testing.T) {
167		ok := map[string]string{
168			"2026-01-02T15:04:05Z":           "2026-01-02T15:04:05Z",
169			"2026-01-02T23:04:05+08:00":      "2026-01-02T15:04:05Z",
170			"2026-01-02T10:04:05-05:00":      "2026-01-02T15:04:05Z",
171			"2026-01-02T15:04:05.1Z":         "2026-01-02T15:04:05.1Z",
172			"2026-01-02T15:04:05.123456789Z": "2026-01-02T15:04:05.123456789Z",
173			"2026-01-02T15:04:05.100000000Z": "2026-01-02T15:04:05.1Z",
174			"2026-01-02T15:04:05.000000000Z": "2026-01-02T15:04:05Z",
175			"2026-01-02T15:04:05+00:00":      "2026-01-02T15:04:05Z",
176		}
177		for in, want := range ok {
178			results := runNormalize(t, `{"time":"`+in+`","action":"a"}`)
179			if results[0]["ok"] != true {
180				t.Fatalf("timestamp %q should parse, got %#v", in, results[0])
181			}
182			if got := eventOf(t, results[0])["timestamp"]; got != want {
183				t.Fatalf("timestamp %q -> %v, want %q", in, got, want)
184			}
185		}
186		bad := []string{
187			"2026-01-02T15:04:05",             // no timezone
188			"2026-01-02t15:04:05z",            // lowercase t/z
189			"2026-01-02T15:04:05.1234567890Z", // 10 fractional digits
190			"2026-01-02T15:04:05.123456789012Z",
191			"2026-01-02T15:04:05.Z",    // dot without digits
192			"2026-01-02T15:04:05+0800", // non-RFC3339 offset
193			"2026-13-02T15:04:05Z",     // month out of range
194			"not-a-time",
