64	// normalizeChunked runs NormalizeReader over input delivered in the given
65	// chunk-size pattern and returns the exact output bytes and failure count.
66	func normalizeChunked(t *testing.T, input string, sizes []int) (string, int) {
67		t.Helper()
68		var out bytes.Buffer
69		failures, err := NormalizeReader(&chunkReader{data: []byte(input), sizes: sizes}, &out)
70		if err != nil {
71			t.Fatalf("chunked delivery must not turn into a stream error, got %v", err)
72		}
