88		for _, pattern := range chunkPatterns {
89			t.Run(pattern.name, func(t *testing.T) {
90				got, failures := normalizeChunked(t, input, pattern.sizes)
91				if got != base {
92					t.Fatalf("chunking changed the output\nwhole:   %q\nchunked: %q", base, got)
93				}
94				if failures != baseFailures {
95					t.Fatalf("chunking changed the failure count: got %d, want %d", failures, baseFailures)
96				}
97			})
