24	// escKey renders key as a JSON member name spelled entirely with unicode
25	// escapes (with UTF-16 surrogate pairs above the BMP), so tests can feed a
26	// \uXXXX-encoded key without embedding escape text in the source.
27	func escKey(key string) string {
28		var b strings.Builder
29		b.WriteByte('"')
30		for _, r := range key {
31			for _, u := range utf16.Encode([]rune{r}) {
32				fmt.Fprintf(&b, "\\u%04x", u)
33			}
34		}
35		b.WriteByte('"')
36		return b.String()
37	}
