39	// normalizeBin is the compiled relayproof binary shared by all tests in
40	// this package, built once from the current sources.
41	var normalizeBin string
42	
43	func TestMain(m *testing.M) {
44		dir, err := os.MkdirTemp("", "relayproof-cli-test")
45		if err != nil {
46			panic(err)
47		}
48		defer os.RemoveAll(dir)
49	
50		normalizeBin = filepath.Join(dir, "relayproof")
51		build := exec.Command("go", "build", "-o", normalizeBin, ".")
52		if out, err := build.CombinedOutput(); err != nil {
53			panic("building relayproof for CLI tests: " + err.Error() + "\n" + string(out))
54		}
55		os.Exit(m.Run())
56	}
