58	// cliResult captures everything the surrounding shell can observe from one
59	// normalize invocation.
60	type cliResult struct {
61		stdout   string
62		stderr   string
63		exitCode int
64	}
65	
66	// runNormalizeCLI executes `relayproof normalize` with stdin fed from r and
67	// records stdout, stderr, and the exit code. A process that cannot be
68	// started at all fails the test rather than masquerading as an exit status.
69	func runNormalizeCLI(t *testing.T, stdin io.Reader) cliResult {
70		t.Helper()
71		cmd := exec.Command(normalizeBin, "normalize")
72		cmd.Stdin = stdin
73		var stdout, stderr bytes.Buffer
74		cmd.Stdout = &stdout
75		cmd.Stderr = &stderr
76	
77		err := cmd.Run()
78		result := cliResult{stdout: stdout.String(), stderr: stderr.String()}
79		switch {
80		case err == nil:
81			result.exitCode = 0
82		default:
83			exitErr, ok := err.(*exec.ExitError)
84			if !ok {
85				t.Fatalf("normalize process could not run: %v", err)
86			}
87			result.exitCode = exitErr.ExitCode()
88		}
89		return result
90	}
91	
92	// decodeStdoutResults parses stdout as newline-delimited JSON result
93	// objects. Any line that is not a JSON object — help text, a plain-text
94	// notice, a log fragment — fails the test, because stdout must carry
95	// machine-readable results and nothing else.
96	func decodeStdoutResults(t *testing.T, stdout string) []map[string]any {
97		t.Helper()
98		var results []map[string]any
99		decoder := json.NewDecoder(strings.NewReader(stdout))
100		for {
101			var record map[string]any
102			if err := decoder.Decode(&record); err != nil {
103				if err == io.EOF {
104					return results
105				}
106				t.Fatalf("stdout must contain only JSON result objects, got decode error %v after %d records: %q",
107					err, len(results), stdout)
108			}
109			results = append(results, record)
110		}
111	}
112	
113	// eventOf extracts the event object of a successful result.
114	func eventOf(t *testing.T, result map[string]any) map[string]any {
115		t.Helper()
116		event, ok := result["event"].(map[string]any)
117		if !ok {
118			t.Fatalf("result has no event object: %#v", result)
119		}
120		return event
121	}
