123	// A healthy run: every log line normalizes, stdout carries one JSON result
124	// per line and nothing else, stderr stays silent, and the process exits 0.
125	// Alias keys must surface under their canonical names, the timestamp must be
126	// converted to UTC, the action trimmed, and unmapped fields must survive in
127	// extra with their JSON types intact.
128	func TestNormalizeCLIAllValidExitsZero(t *testing.T) {
129		input := `{"time":"2026-01-02T08:04:05+08:00","src_ip":"2001:db8::1","event_type":"  login  ","user":" alice ","retries":2,"ok":true}` + "\n" +
130			`{"timestamp":"2026-01-02T00:00:00Z","action":"logout","source_ip":"10.0.0.9","tags":["a","b"],"meta":{"trace":"t-1"}}` + "\n"
131	
132		result := runNormalizeCLI(t, strings.NewReader(input))
133	
134		if result.exitCode != 0 {
135			t.Fatalf("all-valid input must exit 0, got %d (stderr: %q)", result.exitCode, result.stderr)
136		}
137		if result.stderr != "" {
138			t.Fatalf("a clean run must not write to stderr, got %q", result.stderr)
139		}
140	
141		results := decodeStdoutResults(t, result.stdout)
142		if len(results) != 2 {
143			t.Fatalf("expected one result per input line, got %#v", results)
144		}
145	
146		first := results[0]
147		if first["line"] != float64(1) || first["ok"] != true {
148			t.Fatalf("first result must report line 1 as ok: %#v", first)
149		}
150		event := eventOf(t, first)
151		if event["timestamp"] != "2026-01-02T00:04:05Z" {
152			t.Fatalf("alias time must land in timestamp converted to UTC, got %v", event["timestamp"])
153		}
154		if event["source_ip"] != "2001:db8::1" {
155			t.Fatalf("alias src_ip must land in source_ip, got %v", event["source_ip"])
156		}
157		if event["action"] != "login" {
158			t.Fatalf("alias event_type must land in action with whitespace trimmed, got %v", event["action"])
159		}
160		extra, ok := event["extra"].(map[string]any)
161		if !ok {
162			t.Fatalf("unmapped fields must be kept in extra: %#v", event)
163		}
164		if extra["user"] != " alice " {
165			t.Fatalf("extra strings must pass through verbatim, got %v", extra["user"])
166		}
167		if extra["retries"] != float64(2) {
168			t.Fatalf("extra numbers must stay numbers, got %#v", extra["retries"])
169		}
170		if extra["ok"] != true {
171			t.Fatalf("extra booleans must stay booleans, got %#v", extra["ok"])
172		}
173	
174		second := results[1]
175		if second["line"] != float64(2) || second["ok"] != true {
176			t.Fatalf("second result must report line 2 as ok: %#v", second)
177		}
178		event = eventOf(t, second)
