	var m map[string]json.RawMessage
	for _, in := range []string{
		`{"a":"\uD800"}`,
		`{"a":"\uDC00"}`,
		`{"a":"\uD800\uD800"}`,
		`{"a":"\uD800x"}`,
		`{"a":"\uDC00\uD800"}`,
		`{"a":"😀"}`,
		`{"a":"�"}`,
		"{\"a\":\"\xff\"}",
