		if err != nil {
			fmt.Printf("%q token err: %v\n", in, err)
			continue
		}
		_ = tok
		err = dec.Decode(&m)
		var s string
		_ = json.Unmarshal(m["a"], &s)
		fmt.Printf("%q -> decode err=%v raw=%q unmarshaled=%q validOut=%v\n", in, err, string(m["a"]), s, utf8.ValidString(s))
		m = map[string]json.RawMessage{}
